// Bundles collector/src/worker.ts into lib/server/collector-bundle.ts, the worker MetaInfo uploads to a site's
// Cloudflare account when someone clicks "Deploy to my Cloudflare". Run after changing anything in collector/src:
//   npm run build:collector
import { build } from "esbuild";
import { createHash } from "node:crypto";
import { writeFileSync } from "node:fs";

const out = await build({
  entryPoints: ["collector/src/worker.ts"],
  bundle: true,
  format: "esm",
  target: "es2022",
  platform: "neutral",
  minify: false,
  legalComments: "none",
  write: false,
});
const js = out.outputFiles[0].text;
const version = createHash("sha256").update(js).digest("hex").slice(0, 12);
writeFileSync(
  "lib/server/collector-bundle.ts",
  `// Generated by scripts/build-collector-bundle.mjs from collector/src/worker.ts. Don't edit; run \`npm run build:collector\`.\n` +
    `export const COLLECTOR_VERSION = ${JSON.stringify(version)};\n` +
    `export const COLLECTOR_WORKER_JS = ${JSON.stringify(js)};\n`,
);
console.log(`collector bundle ${version} (${js.length} bytes)`);
